using System;using System.Collections.Generic;using System.Reflection;using System.Runtime.Serialization;using HarmonyLib;using UnityEngine;using Delve;
public class ConsoleCmdSummoningTwenty:ConsoleCmdAbstract {
 static int checks,failures;static EntityPlayerLocal fixture;
 static void Check(bool b,string s){checks++;if(!b){failures++;SdtdConsole.Instance.Output("[Summoning20] CHECK FAILED: "+s);}}
 static bool Player(ref EntityPlayerLocal __result){__result=fixture;return false;}
 static bool NoPractice(){return false;}
 public override string[] getCommands(){return new[]{"summoning20verify"};}
 public override string getDescription(){return "Summoning early talents, Forged chain, UI bindings and native effects.";}
 public override void Execute(List<string> args,CommandSenderInfo sender){var h=new Harmony("delve.summoning20.probe");var entities=new List<EntityAlive>();var world=GameManager.Instance.World;var flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;try{
  checks=failures=0;h.Patch(AccessTools.Method(typeof(Summoning),"Practice"),new HarmonyMethod(AccessTools.Method(typeof(ConsoleCmdSummoningTwenty),"NoPractice")));
  var owner=EntityFactory.CreateEntity(EntityClass.FromString("playerMale"),new Vector3(0,200,0)) as EntityPlayer;owner.world=world;world.Entities.Add(owner.entityId,owner);entities.Add(owner);
  fixture=(EntityPlayerLocal)FormatterServices.GetUninitializedObject(typeof(EntityPlayerLocal));for(Type t=typeof(EntityPlayer);t!=typeof(MonoBehaviour)&&t!=null;t=t.BaseType)foreach(var f in t.GetFields(flags|BindingFlags.DeclaredOnly))if(!f.IsStatic&&f.DeclaringType.IsInstanceOfType(owner))f.SetValue(fixture,f.GetValue(owner));fixture.isEntityRemote=false;fixture.Progression.Level=20;fixture.Buffs.SetCustomVar("delveProgressionVersion",2);CharacterProgression.Initialize(fixture);
  Action<int> rank=r=>{CharacterProgression.Set(fixture,"delvePracticeSummoning",ProficiencyRules.Threshold(r));CharacterProgression.RefreshSkill(fixture,"Summoning");};
  foreach(string n in SummonTalents.Names){var v=owner.Progression.GetProgressionValue("delvePerkSummoning"+n);Check(v!=null,"Native perk "+n);v.Level=0;}
  rank(9);foreach(string n in SummonTalents.Names)Check(!ProgressionRuntime.Eligible(fixture,"delvePerkSummoning"+n),"Rank9 locked "+n);
  rank(10);foreach(string n in SummonTalents.Names){var v=fixture.Progression.GetProgressionValue("delvePerkSummoning"+n);bool basic=n=="BindingDiscipline"||n=="PrimalBond";Check(ProgressionRuntime.Eligible(fixture,v.Name)==basic,"Rank10 eligibility "+n);Check(v.CanPurchase(fixture,1)==basic,"Native rank10 purchase "+n);}
  rank(20);Check(!ProgressionRuntime.Eligible(fixture,"delvePerkSummoningFierceCompanion"),"Rank20 requires fundamentals");
  var rod=ItemClass.GetItem("delveForgedSummoningRod",false);rod.Quality=1;rod.Stats=new ItemValue.Stat[0];float reload=EffectManager.GetValue(PassiveEffects.ReloadSpeedMultiplier,rod,0,owner);
  owner.Progression.GetProgressionValue("delvePerkSummoningBindingDiscipline").Level=1;Check(!ProgressionRuntime.Eligible(fixture,"delvePerkSummoningFierceCompanion"),"Both fundamentals required");
  Check(Math.Abs(EffectManager.GetValue(PassiveEffects.ReloadSpeedMultiplier,rod,0,owner)-reload*1.1f)<.001,"Native reload perk effect");owner.Progression.GetProgressionValue("delvePerkSummoningPrimalBond").Level=1;
  rank(19);Check(!ProgressionRuntime.Eligible(fixture,"delvePerkSummoningFierceCompanion"),"Rank19 branch locked");rank(20);
  foreach(string n in new[]{"FierceCompanion","StalwartCompanion","EnduringPact"}){var v=owner.Progression.GetProgressionValue("delvePerkSummoning"+n);Check(ProgressionRuntime.Eligible(fixture,v.Name)&&v.CanPurchase(fixture,1),"Rank20 branch purchase "+n);v.Level=1;Check(!v.CanPurchase(fixture,2),"No duplicate purchase "+n);}
  Check(CharacterProgression.SpentTalents(fixture)==5,"Five standard talent points spent");
  var body=Summoning.Spawn(owner,new Vector3(0,200,2),1,true);entities.Add(body);Check(body.Health==170&&body.GetMaxHealth()==170,"Forged plus Primal Bond health");Check(Math.Abs(body.Expires-Time.time-75)<.1,"Enduring Pact 75 seconds");Check(body.Fierce&&body.Stalwart&&body.Forged,"Perk/tier snapshot");
  var enemy=EntityFactory.CreateEntity(EntityClass.FromString("delveCorruptedWalker"),new Vector3(0,200,3)) as EntityAlive;enemy.world=world;world.Entities.Add(enemy.entityId,enemy);entities.Add(enemy);
  int before=enemy.Health;var attack=new DamageSourceEntity(EnumDamageSource.External,EnumDamageTypes.Bashing,body.entityId);attack.SetIgnoreConsecutiveDamages(true);enemy.DamageEntity(attack,1,false,0);SdtdConsole.Instance.Output("SUMMON DAMAGE actual="+(before-enemy.Health)+" raw="+SummonRules.Damage(body.Rank,body.Quality,body.Forged,body.Fierce));Check(before-enemy.Health>SummonRules.Damage(body.Rank,body.Quality)&&before-enemy.Health<=SummonRules.Damage(body.Rank,body.Quality,true,true),"Actual Forged/Fierce summon damage upgrade after native mitigation");
  before=body.Health;var incoming=new DamageSourceEntity(EnumDamageSource.External,EnumDamageTypes.Bashing,enemy.entityId);incoming.SetIgnoreConsecutiveDamages(true);body.DamageEntity(incoming,20,false,0);Check(before-body.Health==17,"Actual 15% hostile damage reduction");
  foreach(string n in SummonTalents.Names)owner.Progression.GetProgressionValue("delvePerkSummoning"+n).Level=0;
  Check(body.Fierce&&body.Stalwart&&Math.Abs(body.Expires-Time.time-75)<.5,"Existing summon keeps cast snapshot");
  body=Summoning.Spawn(owner,new Vector3(0,200,2),1,true);entities.Add(body);Check(body.Health==148&&!body.Fierce&&!body.Stalwart&&Math.Abs(body.Expires-Time.time-60)<.1,"Recast applies respec and base duration");
  for(int r=1;r<=20;r++)for(int q=1;q<=6;q++){Check(SummonRules.Health(r,q,true,false)>SummonRules.Health(r,q),"Forged health upgrade at every early rank/quality");Check(SummonRules.Damage(r,q,true,false)>SummonRules.Damage(r,q),"Forged damage upgrade at every early rank/quality");}
  Check(SummonRules.Rod("delveForgedSummoningRod")&&ProficiencyRules.Identify("delveForgedSummoningRod")=="Summoning","Forged cast/skill recognition");Check(TrainingHooks.CraftedSkill("delveForgedSummoningRod","")=="Carpentry","Forged profession");
  var recipes=CraftingManager.GetAllRecipes();Recipe forged=null,template=null;foreach(var r in recipes){if(r.GetName()=="delveForgedSummoningRod")forged=r;if(r.GetName()=="delveForgedMendingTotem")template=r;}Check(forged!=null&&template!=null,"Forged recipe exists");Check(forged.craftingArea==template.craftingArea&&forged.craftingToolType==template.craftingToolType&&forged.ingredients.Count==template.ingredients.Count,"Same proven station/tools as Forged focus");
  for(int i=0;i<forged.ingredients.Count;i++)Check(forged.ingredients[i].itemValue.type==template.ingredients[i].itemValue.type&&forged.ingredients[i].count==template.ingredients[i].count,"Same resource chain "+i);
  CharacterProgression.Set(owner,"delvePracticeCarpentry",ProficiencyRules.Threshold(19));Check(!RecipeProgression.Allowed(forged,owner),"Forged crafting rank19 locked");CharacterProgression.Set(owner,"delvePracticeCarpentry",ProficiencyRules.Threshold(20));Check(RecipeProgression.Allowed(forged,owner)&&forged.IsUnlocked(owner),"Forged crafting rank20 access");Check(forged.GetCraftingTier(owner)==6,"Batch11 quality progression retained");
  var station=new TileEntityWorkstation((Chunk)null);station.SetDisableModifiedCheck(true);station.Queue=new[]{new RecipeQueueItem{Recipe=forged,Multiplier=1,CraftingTimeLeft=0,OneItemCraftTime=1,Quality=6,StartingEntityId=-1}};AccessTools.Method(typeof(TileEntityWorkstation),"HandleRecipeQueue").Invoke(station,new object[]{2f});bool output=false;foreach(var s in station.Output)if(s.itemValue.type==forged.itemValueType)output=s.count==1&&s.itemValue.Quality==6;Check(output,"Native Forged Q6 crafting queue");Check(EffectManager.GetValue(PassiveEffects.DegradationMax,rod)==400,"Forged Q1 durability400");
  var getter=typeof(XUiC_ProgressionScreen).GetProperty("Player",flags).GetGetMethod(true);h.Patch(getter,new HarmonyMethod(AccessTools.Method(typeof(ConsoleCmdSummoningTwenty),"Player")));var ui=new XUiC_ProgressionScreen();typeof(XUiC_ProgressionScreen).GetMethod("SelectTab",flags).Invoke(ui,new object[]{1});typeof(XUiC_ProgressionScreen).GetField("skill",flags).SetValue(ui,SummoningUi.Skill());
  foreach(int node in new[]{0,1,2,6,10}){typeof(XUiC_ProgressionScreen).GetField("node",flags).SetValue(ui,node);typeof(XUiC_ProgressionScreen).GetMethod("SkillDetails",flags).Invoke(ui,null);string text="";ui.GetBindingValueInternal(ref text,"dg_detailtitle");Check(text==SummoningUi.Skill().Perks[node].Name,"Selected talent details "+node);}
  for(int i=0;i<14;i++){string visible="";ui.GetBindingValueInternal(ref visible,"dg_nodevisible"+i);Check(visible==(i==0||i==1||i==2||i==6||i==10?"true":"false"),"Only implemented talent cards visible "+i);}string mastery="";ui.GetBindingValueInternal(ref mastery,"dg_hasmasteries");Check(mastery=="false","No empty mastery screen");
  if(failures>0)throw new Exception(failures+" failed checks");SdtdConsole.Instance.Output("[Summoning20] PASS "+checks+" native rank/purchase gates, five-point cost, UI bindings, perk effects, snapshots, Forged stats, Q6 station output and resource-chain checks.");
 }catch(Exception e){SdtdConsole.Instance.Output("[Summoning20] FAIL "+e);}finally{h.UnpatchSelf();fixture=null;foreach(var e in entities)if(e!=null){world.RemoveEntity(e.entityId,EnumRemoveEntityReason.Despawned);if(e!=null&&e.gameObject!=null)UnityEngine.Object.Destroy(e.gameObject);}Summoning.Reset();}}
}
